on conflict (ubigeo) do nothing;

-- ---------------------------------------------------------- ferreterías ---
-- Falta una restricción: sin ella se pueden crear dos ferreterías con el
-- mismo nombre, y el cargador no sabría a cuál asociar los precios.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'uq_ferreteria_nombre') then
    alter table m_ferreterias add constraint uq_ferreteria_nombre unique (nombre);
  end if;
end $$;

on conflict (nombre) do nothing;

on conflict (codigo) do nothing;

-- ------------------------------------------------------------ catálogos ---
  on conflict (nombre) do nothing;

  on conflict (nombre) do nothing;

on conflict (nombre) do nothing;

  on conflict (codigo) do nothing;

on conflict (nombre) do nothing;

on conflict (nombre) do nothing;

on conflict (id_producto, id_marca, id_unidad_medida) do nothing;

-- -------------------------------------------------------------- precios ---
on conflict (id_sede, id_sku) do nothing;

-- 264 precios cargados. 102 quedaron fuera porque su
